function rolePerms(role){
  const all={};PERMS.forEach(p=>all[p.k]=true);
  const none={};PERMS.forEach(p=>none[p.k]=false);
  const base={...none,dashboard:true,leads_view:true,segment_btob:true,segment_btoc:true,fiche_comments:true,fiche_history:true,fiche_docs:true};
  if(role==='superadmin'||role==='admin')return {...all};
  if(role==='manager')return {...all,users_manage:false,settings_access:false,settings_societe:false,settings_operations:false,settings_statuts:false,settings_partenaires:false,settings_delegataires:false,docs_manage:false,compta_apf_delete:false};
  if(role==='confirmateur')return {...base,status_change:true,planning_view:true,rdv_manage:true,rappels_view:true};
  if(role==='commercial')return {...base,leads_create:true,leads_edit:true,status_change:true,clients_view:true,planning_view:true,rdv_manage:true,rappels_view:true,docs_generate:true};
  if(role==='telepro')return {...base,leads_create:true,status_change:true,planning_view:true,rdv_manage:true,rappels_view:true};
  if(role==='poseur')return {...none,dashboard:true,clients_view:true,planning_view:true,rdv_manage:true,sav_view:true};
  return {...none};
}

