/* Pages concernées par le segment — seules celles-ci affichent le sélecteur */
const SEG_PAGES=['dash','dashglobal','leads','clients','planning','rappels','sav','compta','settings'];
/* Rappel visuel du segment en cours, pour les modules à données séparées */
function segBanner(){
  if(segAllowed().length<2)return '';
  const s=SEGMENTS[SEGMENT];
  const col=SEGMENT==='btoc'?'var(--purple)':'var(--blue)';
  const bg=SEGMENT==='btoc'?'rgba(123,95,214,.09)':'rgba(45,125,210,.09)';
  return `<div style="display:flex;align-items:center;gap:.5rem;background:${bg};border-left:3px solid ${col};border-radius:0 8px 8px 0;padding:.4rem .8rem;margin-bottom:.9rem;font-size:.78rem">
    <span>${s.ic}</span><span style="font-weight:700;color:${col}">${esc(s.label)}</span>
    <span class="muted" style="font-size:.72rem">— données propres à ce segment</span>
  </div>`;
}
function segAllowed(){return Object.keys(SEGMENTS).filter(k=>can('segment_'+k));}
function renderSegSwitch(){
  const el=document.getElementById('segSwitch');if(!el)return;
  const allowed=segAllowed();
  // Masqué si la page ne s'y prête pas ou si un seul segment est autorisé
  if(!SEG_PAGES.includes(CUR)||allowed.length<2){el.style.display='none';return;}
  if(!allowed.includes(SEGMENT))setSegment(allowed[0]);
  const recs=getRecs().filter(recVisible);
  el.innerHTML=allowed.map(k=>{
    const nb=recs.filter(r=>segOf(r)===k).length;
    return `<button class="seg-btn ${SEGMENT===k?'on':''}" data-seg="${k}" onclick="switchSegment('${k}')" title="${esc(SEGMENTS[k].label)}">
      ${SEGMENTS[k].ic} <span class="seg-lbl">${SEGMENTS[k].short}</span>${nb?`<span class="seg-count">${nb}</span>`:''}
    </button>`;
  }).join('');
  el.style.display='flex';
}
function switchSegment(k){
  if(SEGMENT===k)return;
  setSegment(k);
  // Réinitialise les filtres de liste, qui référencent statuts et opérations de l'autre segment
  if(typeof LF==='object'){LF.status='';LF.prod='';}
  buildNav();        // compteurs leads / clients du nouveau segment
  renderSegSwitch(); // pastilles du sélecteur
  if(PAGES[CUR])PAGES[CUR].r();
  toast(`${SEGMENTS[k].ic} Segment ${SEGMENTS[k].short}`,'ok');
}
/* Fusionne une liste propre à un segment dans la liste complète, sans toucher l'autre segment */
function mergeSeg(all,segList){
  const ids=new Set(segList.map(x=>x.id));
  return all.filter(x=>!ids.has(x.id)).concat(segList);
}
