/* ---- TVA : tous les montants saisis dans le CRM sont réputés TTC — le HT et la TVA sont calculés et affichés partout ---- */
const tvaRate=()=>{const t=parseFloat((getSettings()||{}).tvaRate);return isNaN(t)?20:t;};
const htOf=n=>(n||0)/(1+tvaRate()/100);
const tvaOf=n=>(n||0)-htOf(n);
const fmtEur=n=>(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2})+' €';
const htSub=n=>`<span style="display:block;font-size:.64rem;font-weight:500;color:var(--text-mut)">HT ${fmtEur(htOf(n))} · TVA ${fmtEur(tvaOf(n))}</span>`;
/* ---- Gestion HT/TTC par ligne de charge ---- */
function getDefaultTvaMode(r,key){
  if(key==='poseur'){const fam=load('egncrm_poseurs',[]).find(f=>(f.userIds||[]).includes(comptaOf(r).poseurUserId));return fam?fam.tvaMode||'ttc':'ttc';}
  if(key==='callcenter'){const src=getSources().find(s=>s.id===r.sourceId);return src?src.tvaMode||'ttc':'ttc';}
  if(key==='vt'){const vt=load('egncrm_vt',[]).find(v=>v.id===comptaOf(r).vtSubId);return vt?vt.tvaMode||'ttc':'ttc';}
  if(key==='audit'){const aud=load('egncrm_auditeurs',[]).find(a=>a.id===comptaOf(r).auditSubId);return aud?aud.tvaMode||'ttc':'ttc';}
  return 'ttc';
}
function effectiveTvaMode(r,key){const c=comptaOf(r);return(c.tvaModes||{})[key]||getDefaultTvaMode(r,key);}
/* Le montant saisi EST du HT ou du TTC selon le mode choisi.
   - TTC      : la TVA est incluse   -> HT = montant / (1+t)
   - HT       : la TVA vient en plus -> TTC = montant * (1+t)
   - Sans TVA : aucune TVA           -> HT = TTC = montant
   `paye` est ce qui sort réellement de la trésorerie (TTC). */
function tvaLine(r,key,montant){
  const mode=effectiveTvaMode(r,key);
  const t=tvaRate()/100;
  const m=montant||0;
  if(mode==='ht'){
    const tva=m*t;
    return{mode:'ht',saisi:m,ht:m,tva,ttc:m+tva,paye:m+tva,tvaRecup:tva};
  }
  if(mode==='sans_tva'){
    return{mode:'sans_tva',saisi:m,ht:m,tva:0,ttc:m,paye:m,tvaRecup:0,tvaNA:true};
  }
  const ht=t?m/(1+t):m;
  return{mode:'ttc',saisi:m,ht,tva:m-ht,ttc:m,paye:m,tvaRecup:0};
}
async function saveTvaMode(recId,key,mode){
  const r=recById(recId);if(!r)return;
  const c=comptaOf(r);c.tvaModes=c.tvaModes||{};c.tvaModes[key]=mode;
  await persistCompta(recId);openDossier(recId);toast('Mode TVA mis à jour ✓','ok');
}
const statById=id=>getAllStatuses().find(s=>s.id===id);
const userById=id=>getUsers().find(u=>u.id===id);
