async function nextDossier(){
  for(let i=0;i<3;i++){
    try{const{data,error}=await SUPA.rpc('next_dossier_number');if(error)throw error;if(data)return data;}
    catch(e){console.error('[nextDossier] tentative '+(i+1)+' échouée',e);if(i<2)await new Promise(r=>setTimeout(r,400));}
  }
  // repli hors-ligne : suffixe horodaté unique -> aucun risque de collision entre deux appareils
  return 'ND-'+new Date().getFullYear()+'-LOC-'+Date.now().toString(36).toUpperCase();
}
async function renumeroterDossier(recId){
  const r=recById(recId);if(!r)return;
  const ancien=r.dossier||'';
  toast('Attribution d\'un numéro définitif…','ok');
  const num=await nextDossier();
  if(num.includes('-LOC-')){toast('Supabase toujours injoignable — réessayez plus tard','err');return;}
  const recs=getRecs();const rec=recs.find(x=>x.id===recId);if(!rec)return;
  rec.dossier=num;rec.updated=Date.now();
  rec.history=rec.history||[];
  rec.history.unshift({date:Date.now(),user:ME.prenom,text:`Numéro de dossier corrigé : ${ancien} → ${num}`});
  save(K.recs,recs);
  openDossier(recId);toast('Nouveau numéro : '+num,'ok');
}
async function nextApfNum(){
  try{const{data,error}=await SUPA.rpc('next_apf_number');if(error)throw error;if(data)return data;}
  catch(e){console.error('[nextApfNum] centralisé indisponible, repli local',e);}
  return 'APF-'+new Date().getFullYear()+'-LOC-'+Date.now().toString(36).toUpperCase();
}

