/* Segment d'un lot de dossiers : déduit du premier dossier retrouvé */
function segmentOfRecIds(recIds){
  for(const id of (recIds||[])){
    const r=recById(id);
    if(r)return segOf(r);
  }
  return null; // aucun dossier retrouvé : on n'exclut pas
}
/* APF du segment courant — déduit des dossiers facturés */
function segFactures(){
  return (FACTURES_CACHE||[]).filter(f=>{
    const s=segmentOfRecIds((f.lignes||[]).map(l=>l.recId));
    return s===null||s===SEGMENT;
  });
}
