/* Complète les permissions d'un compte existant avec les nouvelles clés,
   en reprenant la valeur par défaut de son rôle — évite toute perte d'accès. */
function normalizePerms(perms,role){
  const def=rolePerms(role||'telepro');
  const out={};
  PERMS.forEach(p=>{out[p.k]=(perms&&perms[p.k]!==undefined)?!!perms[p.k]:!!def[p.k];});
  return out;
}
function can(p){return ME&&(ME.role==='superadmin'||(ME.perms&&ME.perms[p]===true));}
async function doLogin(){
  const code=document.getElementById('loginCode').value.trim().toUpperCase();
  const pwd=document.getElementById('loginPwd').value;
  const errEl=document.getElementById('loginErr');
  errEl.style.display='none';
  if(!code||!pwd){errEl.textContent='Code et mot de passe requis';errEl.style.display='block';return;}
  const authEmail=code.toLowerCase()+'@'+AUTH_DOMAIN;
  const{data,error}=await SUPA.auth.signInWithPassword({email:authEmail,password:pwd});
  if(error||!data.session){console.error('[Supabase login error]',error);errEl.textContent='Connexion refusée : '+(error?error.message:'session non créée');errEl.style.display='block';return;}
  const{data:profile,error:profErr}=await SUPA.from('profiles').select('*').eq('id',data.user.id).single();
  if(profErr||!profile){console.error('[Supabase profile error]',profErr);errEl.textContent='Profil introuvable : '+(profErr?profErr.message:'aucune ligne')+' — contactez un administrateur';errEl.style.display='block';await SUPA.auth.signOut();return;}
  if(!profile.active){errEl.textContent='Ce compte est désactivé';errEl.style.display='block';await SUPA.auth.signOut();return;}
  ME={id:profile.id,code:profile.code,prenom:profile.prenom,nom:profile.nom,email:profile.email,team:profile.team,role:profile.role,perms:normalizePerms(profile.perms,profile.role),active:profile.active,assignedUsers:profile.assigned_users||[],sourceId:profile.source_id||''};
  startApp();
}
