function zoneClimatiqueOf(r){const d=deptFromCP(r.cp);return ZONE_CLIMATIQUE[d]||'';}
/* ---- date de la visite technique = date du dernier RDV "Visite technique" du dossier ---- */
function dateVisiteVt(r){
  const rdv=subAssignedFor(r,'vt');
  return rdv?rdv.date:'';
}
/* Date d'installation : dernier RDV de pose du dossier */
function dateInstallation(r){
  const rdvs=rdvsOf(r)
    .filter(x=>rdvKind(x.type)==='poseur')
    .sort((a,b)=>((a.date||'')+(a.heure||'')).localeCompare((b.date||'')+(b.heure||'')));
  return rdvs.length?rdvs[rdvs.length-1].date:'';
}
/* Meme date, au format francais, prete a l'affichage */
function dateInstallationFr(r){
  const d=dateInstallation(r);
  if(!d)return '';
  const s=String(d).trim();
  if(s.includes('/'))return s;
  const p=s.split('-');
  return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:s;
}
/* ---- coût énergie actuel estimé = consommation saisie (manuelle) × tarif configuré ---- */
function coutEnergieActuel(consommation,typeEnergie){
  const s=getSettings();
  const prix=(s.tarifsEnergie&&s.tarifsEnergie[typeEnergie])||0;
  return (parseFloat(consommation)||0)*prix;
}
/* ---- déperditions thermiques — méthode NF EN 12831 simplifiée (estimation) ----
   Q (kW) = Σ [U (W/m².K) × Surface (m²) × ΔT (K)] / 1000 pour chaque paroi, + ventilation, + majoration ponts thermiques.
   Réservé Admin/Super Admin. Résultat toujours indicatif ("estimé"), pas un calcul réglementaire certifié. */
const TBASE_ZONE={H1:-10,H2:-7,H3:-2};
const PONTS_THERMIQUES_FORFAIT=0.20; // +20%, valeur usuelle par défaut
const MARGE_SECURITE_DIM=0.20; // +20% sur la puissance dimensionnée
function coefU(typeId){const list=load('egncrm_coefsu',[]);const c=list.find(x=>x.id===typeId);return c?(parseFloat(c.uValue)||0):0;}
function computeDeperditions(r){
  const e=etudeOf(r);
  const zone=zoneClimatiqueOf(r);
  const tbase=TBASE_ZONE[zone];
  if(tbase==null)return null; // zone climatique inconnue (CP manquant/hors table)
  const ti=e.tempInterieure!=null?e.tempInterieure:20;
  const dT=ti-tbase;
  if(dT<=0)return null;
  const uMur=coefU(e.typeMur),uFen=coefU(e.typeFenetre),uPb=coefU(e.typePlancherBas),uPh=coefU(e.typePlancherHaut);
  const qMurs=(uMur*(e.surfaceMurs||0)*dT)/1000;
  const qFenetres=(uFen*(e.surfaceFenetres||0)*dT)/1000;
  const qPlancherBas=(uPb*(e.surfacePlancherBas||0)*dT)/1000;
  const qPlancherHaut=(uPh*(e.surfacePlancherHaut||0)*dT)/1000;
  const qVentilation=(0.34*(e.volumeChauffe||0)*(e.tauxRenouvAir!=null?e.tauxRenouvAir:0.6)*dT)/1000;
  const sousTotal=qMurs+qFenetres+qPlancherBas+qPlancherHaut+qVentilation;
  const qPonts=sousTotal*PONTS_THERMIQUES_FORFAIT;
  const total=sousTotal+qPonts;
  const puissanceDimensionnee=total*(1+MARGE_SECURITE_DIM);
  const postes=[
    {label:'Renouvellement d\'air (ventilation)',kw:qVentilation},
    {label:'Murs',kw:qMurs},
    {label:'Fenêtres et portes',kw:qFenetres},
    {label:'Ponts thermiques (forfait +'+(PONTS_THERMIQUES_FORFAIT*100)+'%)',kw:qPonts},
    {label:'Plancher bas',kw:qPlancherBas},
    {label:'Plancher haut / combles',kw:qPlancherHaut}
  ].map(p=>({...p,part:total>0?(p.kw/total*100):0})).sort((a,b)=>b.kw-a.kw);
  return{zone,tbase,ti,dT,postes,total,puissanceDimensionnee,margePct:MARGE_SECURITE_DIM*100};
}
/* ---- Facteur R (BAT-TH-163 et fiches similaires) = puissance PAC / puissance totale chaufferie (PAC + appoint) ---- */
/* ---- sélection automatique de la PAC la plus adaptée à la puissance requise ----
   Choisit la plus petite PAC du catalogue qui couvre le besoin ; à défaut, la plus puissante disponible. */
/* ---- Thermitube / AGRI-EQ-108 : métrage linéaire, devis estimé, cumac indicatif ----
   Métrage linéaire = Longueur de la serre × Nb rangs par chapelle × Nb chapelles (sauf saisie manuelle qui prévaut).
   kWh cumac (indicatif) = 390 × Surface de la serre (m²) — coefficient fourni par l'utilisateur pour AGRI-EQ-108. */
const THERMITUBE_COEF_CUMAC=390;
function computeThermitube(r){
  const e=etudeOf(r);
  const surface=surfaceFieldValue(r);
  const auto=(e.longueurSerre||0)*(e.nbRangsChapelle||0)*(e.nbChapelles||0);
  const metrage=(e.metrageLineaireManuel!=null&&e.metrageLineaireManuel!=='')?parseFloat(e.metrageLineaireManuel):auto;
  const s=getSettings();
  const prixMl=s.tarifThermitube||0;
  const coutCalcule=metrage*prixMl; // coût théorique métrage × tarif — indicatif uniquement, sert de comparaison
  const cumacEstime=surface?Math.round(THERMITUBE_COEF_CUMAC*surface):0;
  const primeCEE=primeOf(r)||0;
  const devisEstime=primeCEE; // dans l'étude uniquement : le devis présenté = la prime CEE (reste à payer = 0€) — géré manuellement partout ailleurs (Comptabilité)
  return{surface,auto,metrage,prixMl,coutCalcule,devisEstime,primeCEE,cumacEstime,manuel:e.metrageLineaireManuel!=null&&e.metrageLineaireManuel!==''};
}
function bestPacFor(puissanceRequise){
  const list=load('egncrm_pac',[]);
  if(!list.length||!puissanceRequise)return null;
  const suffisantes=list.filter(p=>(parseFloat(p.puissance)||0)>=puissanceRequise).sort((a,b)=>(parseFloat(a.puissance)||0)-(parseFloat(b.puissance)||0));
  if(suffisantes.length)return suffisantes[0];
  return list.slice().sort((a,b)=>(parseFloat(b.puissance)||0)-(parseFloat(a.puissance)||0))[0];
}
function computeFacteurR(r){
  const e=etudeOf(r);
  const pac=load('egncrm_pac',[]).find(x=>x.id===e.pacCatalogueId);
  const puissancePac=pac?(parseFloat(pac.puissance)||0):0;
  const puissanceTotale=parseFloat(e.puissanceTotaleChaufferie)||0;
  if(!puissancePac||!puissanceTotale)return null;
  const pct=puissancePac/puissanceTotale*100;
  return{puissancePac,puissanceTotale,pct,r:pct>=40?1:0,conforme:pct>=40};
}
