async function openEtudePanel(recId){
  if(!ME||(ME.role!=='superadmin'&&ME.role!=='admin')){toast('Réservé Admin / Super Admin','err');return;}
  const r=recById(recId);if(!r)return;
  const op=getAllProducts().find(p=>p.id===r.productId);
  if(!op||!ETUDE_TYPES[op.etudeType]||!op.etudeType){toast('Le module Étude n\'est activé que pour les opérations qui en ont un type configuré — vérifiez Paramètres ▸ Opérations','err');return;}
  await loadEtudeFor(recId);
  if(op.etudeType==='thermitube')renderEtudePanelThermitube(recId);
  else renderEtudePanel(recId);
}
