function thermitubePreviewHtml(t){
  const eur=n=>(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2})+' €';
  if(!t.surface)return `<p class="muted" style="font-size:.78rem;color:#E63946">⚠️ Renseignez le champ « Surface (m²) » sur la fiche du dossier pour estimer le cumac.</p>`;
  return `<div class="tbl-wrap"><table class="tbl"><tbody>
    <tr><td>Métrage linéaire ${t.manuel?'(saisie manuelle)':'(calculé automatiquement)'}</td><td style="text-align:right;font-weight:700">${t.metrage.toLocaleString('fr-FR')} ml</td></tr>
    <tr><td>Coût calculé (${t.prixMl} €/ml) <span class="muted" style="font-size:.62rem">— indicatif, comparaison uniquement</span></td><td style="text-align:right">${eur(t.coutCalcule)}</td></tr>
    <tr><td>kWh cumac estimé (390 × ${t.surface} m²)</td><td style="text-align:right;font-weight:700;color:var(--green-deep)">${t.cumacEstime.toLocaleString('fr-FR')} kWhc</td></tr>
    <tr><td><b>Devis présenté dans l'étude</b> <span class="muted" style="font-size:.62rem">(= Prime CEE TTC du Deal — reste à payer 0 €)</span></td><td style="text-align:right;font-weight:800;color:#2D5F14">${eur(t.devisEstime)}<span style="display:block;font-size:.64rem;font-weight:500;color:var(--text-mut)">HT ${eur(htOf(t.devisEstime))}</span></td></tr>
  </tbody></table></div><p class="muted" style="font-size:.7rem;margin-top:.3rem">💡 Ce devis "présenté" ne sert que dans le document d'étude — la Comptabilité et le reste du dossier restent gérés manuellement comme d'habitude. Pense à renseigner la prime dans le panneau Deal avant de générer le PDF.</p>`;
}
function recalcThermitubePreview(recId){
  const r=recById(recId);if(!r)return;
  const e=etudeOf(r);
  e.longueurSerre=parseFloat(String(val('th_longueur')||'').replace(',','.'))||null;
  e.nbRangsChapelle=parseFloat(String(val('th_rangs')||'').replace(',','.'))||null;
  e.nbChapelles=parseFloat(String(val('th_chapelles')||'').replace(',','.'))||null;
  const manuelVal=val('th_manuel');
  e.metrageLineaireManuel=(manuelVal!=null&&manuelVal!=='')?parseFloat(String(manuelVal).replace(',','.')):null;
  document.getElementById('th_preview').innerHTML=thermitubePreviewHtml(computeThermitube(r));
}
