  openModal('Étude technique — '+esc(recName(r)),body,`<button class="btn btn-ghost" onclick="closeModal()">Fermer</button><button class="btn btn-navy" onclick="saveEtudeForm('${recId}')">💾 Enregistrer</button><button class="btn btn-pri" onclick="saveEtudeForm('${recId}',true)">📄 Enregistrer & Générer le PDF</button>`,'wide');
