function deperditionsPreviewHtml(deperd){
  if(!deperd)return `<p class="muted" style="font-size:.78rem">Renseignez la zone climatique (CP du dossier) et au moins la température intérieure pour voir l'aperçu du calcul.</p>`;
  const eur=n=>(n||0).toLocaleString('fr-FR',{maximumFractionDigits:1});
  return `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Poste de déperdition</th><th style="text-align:right">Puissance</th><th style="text-align:right">Part</th></tr></thead><tbody>
    ${deperd.postes.map(p=>`<tr><td>${esc(p.label)}</td><td style="text-align:right">${eur(p.kw)} kW</td><td style="text-align:right">${eur(p.part)} %</td></tr>`).join('')}
    <tr style="font-weight:700"><td>Déperditions totales</td><td style="text-align:right">${eur(deperd.total)} kW</td><td style="text-align:right">100 %</td></tr>
    <tr style="font-weight:700;color:var(--green-deep)"><td>Puissance dimensionnée (+${deperd.margePct}%)</td><td style="text-align:right" colspan="2">${eur(deperd.puissanceDimensionnee)} kW</td></tr>
  </tbody></table></div><p class="muted" style="font-size:.7rem;margin-top:.3rem">ΔT = ${deperd.ti}°C (intérieur) − ${deperd.tbase}°C (Tbase zone ${deperd.zone}) = ${deperd.dT} K · Estimation indicative, pas un calcul réglementaire certifié.</p>`;
}
function factRPreviewHtml(factR){
  if(!factR)return `<p class="muted" style="font-size:.78rem">Choisissez une solution PAC et renseignez la puissance totale de chaufferie pour calculer le Facteur R.</p>`;
  return `<div class="callout" style="background:${factR.conforme?'rgba(124,194,66,.12)':'rgba(230,57,70,.1)'};padding:.6rem .9rem;border-radius:8px;font-size:.82rem"><b>Facteur R</b> = ${factR.puissancePac} kW (PAC) ÷ ${factR.puissanceTotale} kW (total) = <b>${factR.pct.toFixed(1)}%</b> → R = ${factR.r} — ${factR.conforme?'<span style="color:var(--green-deep);font-weight:700">✓ Conforme (≥ 40%)</span>':'<span style="color:#E63946;font-weight:700">✗ Non conforme (< 40%)</span>'}</div>`;
}
function recalcEtudePreview(recId){
  const r=recById(recId);if(!r)return;
  const e=etudeOf(r);
  e.tempInterieure=parseFloat(String(val('et_ti')||'').replace(',','.'));
  e.surfaceMurs=parseFloat(String(val('et_smur')||'').replace(',','.'))||null;
  e.typeMur=val('et_tmur')||'';
  e.surfaceFenetres=parseFloat(String(val('et_sfen')||'').replace(',','.'))||null;
  e.typeFenetre=val('et_tfen')||'';
  e.surfacePlancherBas=parseFloat(String(val('et_spb')||'').replace(',','.'))||null;
  e.typePlancherBas=val('et_tpb')||'';
  e.surfacePlancherHaut=parseFloat(String(val('et_sph')||'').replace(',','.'))||null;
  e.typePlancherHaut=val('et_tph')||'';
  e.volumeChauffe=parseFloat(String(val('et_vol')||'').replace(',','.'))||null;
  e.tauxRenouvAir=parseFloat(String(val('et_taux')||'').replace(',','.'));
  e.pacCatalogueId=val('et_pac')||'';
  e.puissanceTotaleChaufferie=parseFloat(String(val('et_ptot')||'').replace(',','.'))||null;
  document.getElementById('et_deperd_preview').innerHTML=deperditionsPreviewHtml(computeDeperditions(r));
  document.getElementById('et_factr_preview').innerHTML=factRPreviewHtml(computeFacteurR(r));
}
/* ---- photos de chaufferie de l'étude (stockées dans le même bucket protégé que les documents) ---- */
const ETUDE_PHOTO_FIELDS={
  chaufferieGrande:{col:'photoChaufferieGrande',label:'Photo de la chaufferie (grand format, couverture)'},
  chaufferie:{col:'photoChaufferie',label:'Photo de la chaufferie'},
  plaque:{col:'photoPlaque',label:'Photo de la plaque signalétique'},
  ecs:{col:'photoEcs',label:'Photo du préparateur ECS'},
  regulation:{col:'photoRegulation',label:'Photo de la régulation et du raccordement'}
};
async function uploadEtudePhoto(recId,key,file){
  if(!file)return;
  const cfg=ETUDE_PHOTO_FIELDS[key];if(!cfg)return;
  const r=recById(recId);if(!r)return;
  const e=etudeOf(r);
  const path=`${recId}/etude-${key}-${uid()}-${file.name}`.replace(/[^a-zA-Z0-9/_.\-]/g,'_');
  try{
    const{error}=await SUPA.storage.from(ATTACH_BUCKET).upload(path,file,{contentType:file.type||undefined});
    if(error)throw error;
    const oldPath=e[cfg.col];
    e[cfg.col]=path;
    await persistEtude(recId);
    if(oldPath)try{await SUPA.storage.from(ATTACH_BUCKET).remove([oldPath]);}catch(err){}
    toast('Photo ajoutée ✓','ok');
    renderEtudePanel(recId);
  }catch(err){console.error('[uploadEtudePhoto]',err);toast('Échec de l\'envoi de la photo : '+(err.message||err),'err');}
}
async function removeEtudePhoto(recId,key){
  const cfg=ETUDE_PHOTO_FIELDS[key];if(!cfg)return;
  const r=recById(recId);if(!r)return;
  const e=etudeOf(r);
  const path=e[cfg.col];
  if(path)try{await SUPA.storage.from(ATTACH_BUCKET).remove([path]);}catch(err){}
  e[cfg.col]='';
  await persistEtude(recId);
  renderEtudePanel(recId);
}
async function etudePhotoThumbUrl(path){
  if(!path)return '';
  try{return await signedUrl(path);}
  catch(e){console.error('[etudePhotoThumbUrl]',e);return '';}
}
function etudePhotoFieldHtml(recId,key,path){
  const cfg=ETUDE_PHOTO_FIELDS[key];
  const inputId='etph_'+key;
  return `<div class="fld">
    <label>${cfg.label}</label>
    ${path?`<div style="margin-bottom:.4rem" id="${inputId}_thumb"><span class="muted" style="font-size:.72rem">⏳ Chargement de l'aperçu…</span></div>`:''}
    <input type="file" accept="image/*" id="${inputId}" onchange="uploadEtudePhoto('${recId}','${key}',this.files[0])">
    ${path?`<button class="btn btn-ghost btn-sm" style="margin-top:.3rem" onclick="removeEtudePhoto('${recId}','${key}')">🗑️ Retirer la photo</button>`:''}
  </div>`;
}
async function loadEtudePhotoThumbs(recId){
  const r=recById(recId);if(!r)return;
  const e=etudeOf(r);
  for(const key in ETUDE_PHOTO_FIELDS){
    const cfg=ETUDE_PHOTO_FIELDS[key];const path=e[cfg.col];
    const el=document.getElementById('etph_'+key+'_thumb');
    if(!path||!el)continue;
    const url=await etudePhotoThumbUrl(path);
    if(el)el.innerHTML=url?`<img src="${url}" style="max-height:90px;border-radius:6px;border:1px solid var(--border-grey)">`:`<span class="muted" style="font-size:.72rem">Aperçu indisponible</span>`;
  }
}
function suggestPac(recId){
  const r=recById(recId);if(!r)return;
  const e=etudeOf(r);
  // recapture les champs de déperditions actuellement saisis dans le formulaire
  e.tempInterieure=parseFloat(String(val('et_ti')||'').replace(',','.'));
  e.surfaceMurs=parseFloat(String(val('et_smur')||'').replace(',','.'))||null;
  e.typeMur=val('et_tmur')||'';
  e.surfaceFenetres=parseFloat(String(val('et_sfen')||'').replace(',','.'))||null;
  e.typeFenetre=val('et_tfen')||'';
  e.surfacePlancherBas=parseFloat(String(val('et_spb')||'').replace(',','.'))||null;
  e.typePlancherBas=val('et_tpb')||'';
  e.surfacePlancherHaut=parseFloat(String(val('et_sph')||'').replace(',','.'))||null;
  e.typePlancherHaut=val('et_tph')||'';
  e.volumeChauffe=parseFloat(String(val('et_vol')||'').replace(',','.'))||null;
  e.tauxRenouvAir=parseFloat(String(val('et_taux')||'').replace(',','.'));
  const deperd=computeDeperditions(r);
  if(!deperd||!deperd.puissanceDimensionnee){toast('Renseignez d\'abord les surfaces / zone climatique pour calculer le besoin','err');return;}
  const suggested=bestPacFor(deperd.puissanceDimensionnee);
  if(!suggested){toast('Aucune PAC dans le catalogue — ajoutez-en dans Paramètres ▸ Solutions PAC','err');return;}
  e.pacCatalogueId=suggested.id;
  const sel=document.getElementById('et_pac');if(sel)sel.value=suggested.id;
  const note=document.getElementById('et_pac_note');
  if(note)note.innerHTML=`<p class="muted" style="font-size:.72rem;color:var(--green-deep)">✓ PAC suggérée automatiquement : ${esc(suggested.name)} (${suggested.puissance} kW ≥ besoin de ${deperd.puissanceDimensionnee.toFixed(1)} kW)</p>`;
  document.getElementById('et_deperd_preview').innerHTML=deperditionsPreviewHtml(deperd);
  document.getElementById('et_factr_preview').innerHTML=factRPreviewHtml(computeFacteurR(r));
  toast('PAC suggérée : '+suggested.name,'ok');
}
async function fetchEtudePhotoDataUrl(path){
  if(!path)return '';
  try{
    const{data,error}=await SUPA.storage.from(ATTACH_BUCKET).download(path);
    if(error)throw error;
    return await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(data);});
  }catch(e){console.error('[fetchEtudePhotoDataUrl]',path,e);return '';}
}
