  if(!opCheck||opCheck.etudeType!=='pac'){toast('Ce module Étude n\'est activé que pour les opérations de type PAC','err');return;}
  await Promise.all([loadEtudeFor(recId),loadDealFor(recId),loadComptaFor(recId)]);
